import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    header_index = next(
        (i for i, row in enumerate(records) if len(row) == 4),
        None,
    )
    if header_index is None:
        header_index = max(range(len(records)), key=lambda i: len(records[i]))

    columns = list(records[header_index])
    rows = records[header_index + 1:]
    width = max([len(columns)] + [len(row) for row in rows])

    used = set(columns)
    while len(columns) < width:
        base = "column_{}".format(len(columns) + 1)
        name = base
        suffix = 2
        while name in used:
            name = "{}_{}".format(base, suffix)
            suffix += 1
        columns.append(name)
        used.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
